const token=localStorage.getItem('owar-admin-token')||prompt('Enter the admin token'); if(token)localStorage.setItem('owar-admin-token',token); const auth={Authorization:`Bearer ${token}`};
fetch('/api/admin/tree',{headers:auth}).then(r=>r.json()).then(data=>{const byTarget={};data.entries.forEach(x=>(byTarget[x.target_event_id]??=[]).push(x)); const links={};data.rules.forEach(x=>(links[x.source_event_id]??=[]).push(x)); document.querySelector('#tree').innerHTML=data.stages.map(s=>`<section class="tree-stage"><div class="tree-title"><span>${s.phase}</span><h2>${s.label}</h2><small>${s.event_name||'Waiting for import'}</small></div><div class="tree-entries">${(byTarget[s.event_id]||[]).sort((a,b)=>a.target_slot-b.target_slot).map(e=>`<div><b>Slot ${e.target_slot}</b>${e.name}<small>from event ${e.source_event_id}, place ${e.source_position}</small></div>`).join('')||'<p class="hint">No qualified riders yet.</p>'}</div><div class="tree-links">${(links[s.event_id]||[]).map(l=>`Place ${l.position} → event ${l.target_event_id}, slot ${l.target_slot}`).join('<br>')||'No outgoing progression'}</div></section>`).join('')||'<section class="panel"><p class="hint">Set up the tournament first.</p></section>'}).catch(e=>document.querySelector('#tree').textContent=e.message);
